code.Python3:
import sys

def solve(inp):
    tokens = inp.strip().split()
    if not tokens: return ''
    n = int(tokens[0])
    nums = [int(x) for x in tokens[1:n + 1]]
    total = sum(nums)
    out = []
    curr = 0
    for x in nums:
        curr += x
        out.append(str(total - curr))
    return ' '.join(out)


def main():
    s = sys.stdin.read()
    if s.strip():
        print(solve(s))

if __name__ == '__main__':
    main()

code.JavaScript:
const fs = require('fs');
function solve(inp) {
    const tokens = inp.trim().split(/\s+/);
    if (!tokens || tokens.length === 0 || tokens[0] === '') return '';
    const n = parseInt(tokens[0], 10);
    const nums = tokens.slice(1, n + 1).map(Number);
    const total = nums.reduce((a, b) => a + b, 0);
    const out = [];
    let curr = 0;
    for (const x of nums) {
        curr += x;
        out.push(total - curr);
    }
    return out.join(' ');
}
function main() {
    const s = fs.readFileSync(0, 'utf-8').trim();
    if (s.length > 0) console.log(solve(s));
}
main();

